import os
from authlib.integrations.requests_client import OAuth2Session
from authlib.oauth2.rfc6749 import errors as oauth_errors

# Auth0 integration
AUTH0_DOMAIN = os.getenv('AUTH0_DOMAIN')
AUTH0_CLIENT_ID = os.getenv('AUTH0_CLIENT_ID')
AUTH0_CLIENT_SECRET = os.getenv('AUTH0_CLIENT_SECRET')

if not all([AUTH0_DOMAIN, AUTH0_CLIENT_ID, AUTH0_CLIENT_SECRET]):
    raise RuntimeError('Auth0 environment variables not set')

# Create an OAuth2 session
def create_auth0_session():
    return OAuth2Session(
        AUTH0_CLIENT_ID,
        token_endpoint_auth_method='client_secret_post',
        server_metadata={
            'token_endpoint': f'https://{AUTH0_DOMAIN}/oauth/token'
        }
    )

# Sign in user
def sign_in(email, password):
    client = create_auth0_session()
    try:
        token = client.get_token(
            'password',
            body={
                'username': email,
                'password': password,
                'grant_type': 'password',
                'scope': 'openid email profile'
            },
            auth=(AUTH0_CLIENT_ID, AUTH0_CLIENT_SECRET)
        )
        return token
    except oauth_errors.OAuthError as e:
        raise Exception(f'Auth0 token error: {e.description}') from e
